def snake_to_camel(s):
    parts = s.split("_")
    if not parts:
        return s
    result = parts[0]
    for p in parts[1:]:
        if p:
            result += p[0].upper() + p[1:]
    return result

def parse_query(s):
    out = {}
    if not s:
        return out
    for pair in s.split(";"):
        if not pair or "=" not in pair:
            continue
        k, v = pair.split("=", 1)
        k = k.strip(); v = v.strip()
        low = v.lower()
        if low in ("true", "false"):
            out[k] = (low == "true")
        else:
            try:
                out[k] = int(v)
            except ValueError:
                try:
                    out[k] = float(v)
                except ValueError:
                    out[k] = v
    return out

def flatten_dict(d, sep="."):
    out = {}
    def rec(cur, prefix):
        for k, v in cur.items():
            key = prefix + sep + k if prefix else k
            if isinstance(v, dict) and v:
                rec(v, key)
            else:
                out[key] = v
    rec(d, "")
    return out

def run_length_encode(s):
    if not s:
        return ""
    out = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(prev + str(count))
            prev = ch
            count = 1
    out.append(prev + str(count))
    return "".join(out)

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def merge_intervals(intervals):
    if not intervals:
        return []
    s = sorted(intervals, key=lambda x: x[0])
    out = [list(s[0])]
    for iv in s[1:]:
        if iv[0] <= out[-1][1]:
            out[-1][1] = max(out[-1][1], iv[1])
        else:
            out.append(list(iv))
    return out

def shortest_path(graph, start, end):
    import heapq
    dist = {start: 0}
    pq = [(0, start)]
    visited = set()
    while pq:
        d, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        if node == end:
            return d
        for nb, w in graph.get(node, []):
            nd = d + w
            if nd < dist.get(nb, float("inf")):
                dist[nb] = nd
                heapq.heappush(pq, (nd, nb))
    return -1

def longest_increasing_subsequence(nums):
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def process_transactions(ops):
    balance = 0
    for op in ops:
        action, amount = op[0], op[1]
        if amount < 0:
            continue
        if action == "deposit":
            balance += amount
        elif action == "withdraw":
            if amount <= balance:
                balance -= amount
    return balance

def validate_input(schema, data):
    typemap = {"int": int, "str": str, "float": float, "bool": bool}
    errors = []
    for field, tname in schema.items():
        if field not in data:
            errors.append("missing:" + field)
        else:
            val = data[field]
            if tname == "int" and isinstance(val, bool):
                errors.append("type:" + field)
            else:
                expected = typemap.get(tname)
                if expected is not None and not isinstance(val, expected):
                    errors.append("type:" + field)
    return sorted(errors)

def event_emitter(ops):
    handlers = {}
    log = []
    for op in ops:
        kind = op[0]
        if kind == "on":
            _, ev, hid = op
            handlers.setdefault(ev, [])
            if hid not in handlers[ev]:
                handlers[ev].append(hid)
        elif kind == "off":
            _, ev, hid = op
            if ev in handlers and hid in handlers[ev]:
                handlers[ev].remove(hid)
        elif kind == "emit":
            _, ev, payload = op
            for hid in handlers.get(ev, []):
                log.append(hid + ":" + str(payload))
    return log

def dedup_preserve_order(items):
    seen = set()
    out = []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def route_match(routes, path):
    path_parts = [p for p in path.split("/") if p != ""]
    for pattern, handler in routes:
        pat_parts = [p for p in pattern.split("/") if p != ""]
        if len(pat_parts) != len(path_parts):
            continue
        params = {}
        ok = True
        for pp, ap in zip(pat_parts, path_parts):
            if pp.startswith(":"):
                params[pp[1:]] = ap
            elif pp != ap:
                ok = False
                break
        if ok:
            return [handler, params]
    return None

def paginate(items, page, page_size):
    total = len(items)
    if page_size <= 0:
        total_pages = 0
    else:
        total_pages = (total + page_size - 1) // page_size
    if page < 1 or page_size <= 0:
        page_items = []
    else:
        start = (page - 1) * page_size
        page_items = items[start:start + page_size]
    return {
        "items": page_items,
        "page": page,
        "total_pages": total_pages,
        "has_next": page < total_pages,
        "has_prev": page > 1,
    }

def rate_limiter(timestamps, limit, window):
    allowed_times = []
    result = []
    for t in timestamps:
        allowed_times = [x for x in allowed_times if x > t - window]
        if len(allowed_times) < limit:
            result.append(True)
            allowed_times.append(t)
        else:
            result.append(False)
    return result

def parse_query_params(qs):
    out = {}
    if not qs:
        return out
    for pair in qs.split("&"):
        if pair == "":
            continue
        if "=" in pair:
            k, v = pair.split("=", 1)
        else:
            k, v = pair, ""
        out.setdefault(k, []).append(v)
    return out

def check_access(policy, role, resource, action):
    role_policy = policy.get(role)
    if not role_policy:
        return False
    for res in (resource, "*"):
        if res in role_policy:
            actions = role_policy[res]
            if action in actions or "*" in actions:
                return True
    return False

def token_valid(token, now):
    if token.get("revoked"):
        return False
    issued = token.get("issued_at", 0)
    ttl = token.get("ttl", 0)
    if now < issued:
        return False
    return now < issued + ttl

def evaluate_policy(statements, action, resource):
    def matches(patterns, value):
        for p in patterns:
            if p == "*":
                return True
            if p.endswith("*"):
                if value.startswith(p[:-1]):
                    return True
            elif p == value:
                return True
        return False
    allowed = False
    for st in statements:
        if matches(st.get("actions", []), action) and matches(st.get("resources", []), resource):
            if st.get("effect") == "Deny":
                return "Deny"
            elif st.get("effect") == "Allow":
                allowed = True
    return "Allow" if allowed else "Deny"

def apply_migrations(applied, available):
    applied_set = set(applied)
    return [m for m in available if m not in applied_set]

def retry_backoff(results, base, factor, max_delay):
    total = 0
    attempts = 0
    success = False
    for i, r in enumerate(results):
        if i > 0:
            total += min(base * (factor ** (i - 1)), max_delay)
        attempts += 1
        if r:
            success = True
            break
    return {"success": success, "attempts": attempts, "total_delay": total}

def validate_structured_output(schema, obj):
    errors = []
    def check(sch, val, path):
        t = sch.get("type")
        if t == "object":
            if not isinstance(val, dict):
                errors.append(path + ":expected_object")
                return
            base = path + "." if path else ""
            for req in sch.get("required", []):
                if req not in val:
                    errors.append(base + req + ":missing")
            for key, subsch in sch.get("properties", {}).items():
                if key in val:
                    check(subsch, val[key], base + key)
        elif t == "array":
            if not isinstance(val, list):
                errors.append(path + ":expected_array")
                return
            items = sch.get("items")
            if items:
                for idx, item in enumerate(val):
                    check(items, item, path + "[" + str(idx) + "]")
        elif t == "string":
            if not isinstance(val, str):
                errors.append(path + ":expected_string")
        elif t == "integer":
            if isinstance(val, bool) or not isinstance(val, int):
                errors.append(path + ":expected_integer")
        elif t == "number":
            if isinstance(val, bool) or not isinstance(val, (int, float)):
                errors.append(path + ":expected_number")
        elif t == "boolean":
            if not isinstance(val, bool):
                errors.append(path + ":expected_boolean")
        if "enum" in sch and val not in sch["enum"]:
            errors.append(path + ":not_in_enum")
    check(schema, obj, "")
    return sorted(errors)

def token_budget(messages, max_tokens):
    system_msgs = [m for m in messages if m["role"] == "system"]
    used = sum(m["tokens"] for m in system_msgs)
    non_system = [m for m in messages if m["role"] != "system"]
    keep_ids = set()
    for m in reversed(non_system):
        if used + m["tokens"] <= max_tokens:
            used += m["tokens"]
            keep_ids.add(id(m))
        else:
            break
    return [m for m in messages if m["role"] == "system" or id(m) in keep_ids]

def assemble_context(system, chunks, history, max_tokens):
    total = system["tokens"]
    truncated = total > max_tokens
    ordered = sorted(chunks, key=lambda c: (-c["score"], c["id"]))
    chunk_ids = []
    for c in ordered:
        if total + c["tokens"] <= max_tokens:
            total += c["tokens"]
            chunk_ids.append(c["id"])
        else:
            truncated = True
    history_count = 0
    for h in reversed(history):
        if total + h["tokens"] <= max_tokens:
            total += h["tokens"]
            history_count += 1
        else:
            truncated = True
            break
    return {"chunk_ids": chunk_ids, "history_count": history_count,
            "total_tokens": total, "truncated": truncated}

def sigmoid(xs):
    import math
    return [round(1.0 / (1.0 + math.exp(-x)), 6) for x in xs]

def dot_product(a, b):
    if len(a) != len(b):
        raise ValueError('length mismatch')
    return round(sum(x * y for x, y in zip(a, b)), 6)

def min_max_scale(xs):
    if not xs:
        return []
    mn, mx = min(xs), max(xs)
    if mx == mn:
        return [0.0] * len(xs)
    return [round((x - mn) / (mx - mn), 6) for x in xs]

def rmse(y_true, y_pred):
    import math
    if len(y_true) != len(y_pred):
        raise ValueError('length mismatch')
    n = len(y_true)
    if n == 0:
        return 0.0
    return round(math.sqrt(sum((a - b) ** 2 for a, b in zip(y_true, y_pred)) / n), 6)

def cosine_similarity(a, b):
    import math
    if len(a) != len(b):
        raise ValueError('length mismatch')
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        return 0.0
    return round(dot / (na * nb), 6)

def matrix_multiply(A, B):
    n = len(A[0]) if A else 0
    if n != len(B):
        raise ValueError('incompatible dimensions')
    c = len(B[0]) if B else 0
    result = []
    for i in range(len(A)):
        row = []
        for j in range(c):
            row.append(round(sum(A[i][k] * B[k][j] for k in range(n)), 6))
        result.append(row)
    return result

def kmeans_assignment(points, centroids):
    result = []
    for p in points:
        best_i, best_d = 0, None
        for i, c in enumerate(centroids):
            d = sum((a - b) ** 2 for a, b in zip(p, c))
            if best_d is None or d < best_d:
                best_d, best_i = d, i
        result.append(best_i)
    return result

def gini_impurity(labels):
    from collections import Counter
    n = len(labels)
    if n == 0:
        return 0.0
    counts = Counter(labels)
    return round(1.0 - sum((c / n) ** 2 for c in counts.values()), 6)

def one_hot_encode(values, categories=None):
    if categories is None:
        categories = sorted(set(values))
    index = {c: i for i, c in enumerate(categories)}
    result = []
    for v in values:
        row = [0] * len(categories)
        if v in index:
            row[index[v]] = 1
        result.append(row)
    return result

def make_minibatches(n, batch_size):
    if batch_size < 1:
        raise ValueError('batch_size must be >= 1')
    return [list(range(i, min(i + batch_size, n))) for i in range(0, n, batch_size)]

def lr_step_decay(initial_lr, drop, epochs_drop, epoch):
    import math
    if epochs_drop < 1:
        raise ValueError('epochs_drop must be >= 1')
    return round(initial_lr * (drop ** math.floor(epoch / epochs_drop)), 6)

def confusion_matrix(y_true, y_pred, labels):
    index = {l: i for i, l in enumerate(labels)}
    m = [[0] * len(labels) for _ in labels]
    for t, p in zip(y_true, y_pred):
        m[index[t]][index[p]] += 1
    return m

def best_gini_split(feature_values, labels):
    from collections import Counter
    def gini(lbls):
        m = len(lbls)
        if m == 0:
            return 0.0
        c = Counter(lbls)
        return 1.0 - sum((v / m) ** 2 for v in c.values())
    n = len(feature_values)
    uniq = sorted(set(feature_values))
    if len(uniq) < 2:
        return [None, round(gini(labels), 6)]
    thresholds = [(uniq[i] + uniq[i + 1]) / 2 for i in range(len(uniq) - 1)]
    best_t, best_g = None, None
    for t in thresholds:
        left = [labels[i] for i in range(n) if feature_values[i] <= t]
        right = [labels[i] for i in range(n) if feature_values[i] > t]
        wg = (len(left) / n) * gini(left) + (len(right) / n) * gini(right)
        if best_g is None or wg < best_g - 1e-12:
            best_g, best_t = wg, t
    return [round(best_t, 6), round(best_g, 6)]

def early_stopping(val_losses, patience, min_delta):
    best = float('inf')
    best_epoch = 0
    counter = 0
    for i, loss in enumerate(val_losses):
        if loss < best - min_delta:
            best = loss
            best_epoch = i
            counter = 0
        else:
            counter += 1
            if counter >= patience:
                return [i, best_epoch]
    return [len(val_losses) - 1, best_epoch]

def stratified_kfold_indices(labels, k):
    from collections import defaultdict
    if k < 2:
        raise ValueError('k must be >= 2')
    groups = defaultdict(list)
    for i, l in enumerate(labels):
        groups[l].append(i)
    folds = [[] for _ in range(k)]
    for l in sorted(groups):
        for j, idx in enumerate(groups[l]):
            folds[j % k].append(idx)
    return [sorted(f) for f in folds]

def error_slice_metrics(records, slice_key):
    from collections import defaultdict
    groups = defaultdict(list)
    for r in records:
        groups[r[slice_key]].append(r)
    out = {}
    for key, rs in groups.items():
        correct = sum(1 for r in rs if r['y_true'] == r['y_pred'])
        out[key] = round(correct / len(rs), 6)
    return out

def expected_calibration_error(confidences, predictions, labels, n_bins):
    N = len(confidences)
    bins = [[] for _ in range(n_bins)]
    for i, c in enumerate(confidences):
        b = min(int(c * n_bins), n_bins - 1)
        bins[b].append(i)
    ece = 0.0
    for b in bins:
        if not b:
            continue
        acc = sum(1 for i in b if predictions[i] == labels[i]) / len(b)
        conf = sum(confidences[i] for i in b) / len(b)
        ece += (len(b) / N) * abs(acc - conf)
    return round(ece, 6)

def metadata_filter(hits, filters):
    out = []
    for h in hits:
        md = h.get("metadata", {})
        if all(k in md and md[k] == v for k, v in filters.items()):
            out.append(h)
    return out

def top_k_filter(logits, k):
    if k <= 0:
        return []
    order = sorted(range(len(logits)), key=lambda i: (-logits[i], i))
    return order[:k]

def recall_at_k(retrieved, relevant, k):
    rel = set(relevant)
    if not rel:
        return 0.0
    topk = set(retrieved[:k]) if k > 0 else set()
    hit = len(rel & topk)
    return round(hit / len(rel), 4)

def cosine_topk(query, docs, k):
    import math
    def cos(a, b):
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(y * y for y in b))
        if na == 0 or nb == 0:
            return 0.0
        return dot / (na * nb)
    scored = [[i, round(cos(query, d), 4)] for i, d in enumerate(docs)]
    scored.sort(key=lambda p: (-p[1], p[0]))
    if k < 0:
        k = 0
    return scored[:k]

def reciprocal_rank_fusion(rankings, k):
    scores = {}
    for lst in rankings:
        for rank, doc in enumerate(lst, start=1):
            scores[doc] = scores.get(doc, 0.0) + 1.0 / (k + rank)
    out = [[doc, round(s, 6)] for doc, s in scores.items()]
    out.sort(key=lambda p: (-p[1], p[0]))
    return out

def mrr(retrieved_lists, relevant_lists):
    if not retrieved_lists:
        return 0.0
    total = 0.0
    for retrieved, relevant in zip(retrieved_lists, relevant_lists):
        rel = set(relevant)
        rr = 0.0
        for rank, doc in enumerate(retrieved, start=1):
            if doc in rel:
                rr = 1.0 / rank
                break
        total += rr
    return round(total / len(retrieved_lists), 4)

def dedup_by_cosine(vectors, threshold):
    import math
    def cos(a, b):
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(y * y for y in b))
        if na == 0 or nb == 0:
            return 0.0
        return dot / (na * nb)
    kept = []
    for i, v in enumerate(vectors):
        if all(cos(v, vectors[j]) < threshold for j in kept):
            kept.append(i)
    return kept

def token_budget_pack(chunks, budget):
    ordered = sorted(chunks, key=lambda c: (-c["score"], c["id"]))
    used = 0
    out = []
    for c in ordered:
        if used + c["tokens"] <= budget:
            out.append(c["id"])
            used += c["tokens"]
    return out

def top_p_filter(probs, p):
    order = sorted(range(len(probs)), key=lambda i: (-probs[i], i))
    cum = 0.0
    chosen = []
    for i in order:
        chosen.append(i)
        cum += probs[i]
        if cum >= p:
            break
    return sorted(chosen)

def weighted_hybrid_fusion(dense, sparse, alpha):
    def norm(lst):
        if not lst:
            return {}
        vals = [s for _, s in lst]
        lo, hi = min(vals), max(vals)
        out = {}
        for d, s in lst:
            out[d] = 1.0 if hi == lo else (s - lo) / (hi - lo)
        return out
    dn = norm(dense)
    sn = norm(sparse)
    ids = set(dn) | set(sn)
    fused = []
    for d in ids:
        val = alpha * dn.get(d, 0.0) + (1 - alpha) * sn.get(d, 0.0)
        fused.append([d, round(val, 4)])
    fused.sort(key=lambda p: (-p[1], p[0]))
    return fused

def permission_filter(hits, user_roles):
    roles = set(user_roles)
    out = []
    for h in hits:
        allowed = set(h.get("metadata", {}).get("allowed_roles", []))
        if allowed & roles:
            out.append(h)
    return out

def multi_query_dedup(result_lists):
    best = {}
    for li, lst in enumerate(result_lists):
        for rank, doc in enumerate(lst, start=1):
            if doc not in best or rank < best[doc][0] or (rank == best[doc][0] and li < best[doc][1]):
                if doc not in best or rank < best[doc][0]:
                    best[doc] = (rank, li)
    order = sorted(best.items(), key=lambda kv: (kv[1][0], kv[1][1], kv[0]))
    return [doc for doc, _ in order]

def groundedness_overlap(answer, context):
    ans = answer.lower().split()
    if not ans:
        return 0.0
    ctx = set(context.lower().split())
    hit = sum(1 for t in ans if t in ctx)
    return round(hit / len(ans), 4)

def citation_span_map(sentences, sources):
    def content_words(s):
        out = []
        for tok in s.lower().split():
            tok = tok.strip(".,!?;:")
            if len(tok) >= 3:
                out.append(tok)
        return out
    src_tokens = []
    for src in sources:
        toks = set()
        for tok in src["text"].lower().split():
            toks.add(tok.strip(".,!?;:"))
        src_tokens.append((src["id"], toks))
    result = []
    for sent in sentences:
        cw = content_words(sent)
        if not cw:
            result.append([])
            continue
        ids = [sid for sid, toks in src_tokens if all(w in toks for w in cw)]
        result.append(sorted(ids))
    return result

def render_template(template, variables):
    import re
    pat = re.compile(r"\{\{([A-Za-z_][A-Za-z0-9_]*)\}\}")
    def repl(m):
        name = m.group(1)
        if name in variables:
            return str(variables[name])
        return m.group(0)
    return pat.sub(repl, template)

def mmr_select(query, docs, k, lambda_):
    import math
    def cos(a, b):
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(y * y for y in b))
        if na == 0 or nb == 0:
            return 0.0
        return dot / (na * nb)
    n = len(docs)
    limit = min(k, n) if k > 0 else 0
    rel = [cos(query, d) for d in docs]
    selected = []
    remaining = set(range(n))
    while len(selected) < limit:
        best_i = None
        best_score = None
        for i in sorted(remaining):
            if not selected:
                score = rel[i]
            else:
                max_sim = max(cos(docs[i], docs[s]) for s in selected)
                score = lambda_ * rel[i] - (1 - lambda_) * max_sim
            if best_score is None or score > best_score:
                best_score = score
                best_i = i
        selected.append(best_i)
        remaining.discard(best_i)
    return selected

def validate_tool_call(call, schema):
    errors = []
    if call.get("name") != schema.get("name"):
        errors.append("name mismatch")
    params = schema.get("parameters", {})
    props = params.get("properties", {})
    required = params.get("required", [])
    args = call.get("arguments", {})
    for name in required:
        if name not in args:
            errors.append("missing required argument: " + name)
    for name in args:
        if name not in props:
            errors.append("unexpected argument: " + name)
    def type_ok(t, v):
        if t == "string":
            return isinstance(v, str)
        if t == "integer":
            return isinstance(v, int) and not isinstance(v, bool)
        if t == "number":
            return isinstance(v, (int, float)) and not isinstance(v, bool)
        if t == "boolean":
            return isinstance(v, bool)
        if t == "array":
            return isinstance(v, list)
        if t == "object":
            return isinstance(v, dict)
        return True
    for name, v in args.items():
        if name in props:
            t = props[name].get("type")
            if not type_ok(t, v):
                errors.append("type mismatch: " + name)
    return sorted(errors)

def ndcg_at_k(ranking, relevance, k):
    import math
    def dcg(gains):
        return sum(g / math.log2(i + 2) for i, g in enumerate(gains))
    top = ranking[:k] if k > 0 else []
    gains = [relevance.get(d, 0) for d in top]
    ideal = sorted(relevance.values(), reverse=True)[:k] if k > 0 else []
    idcg = dcg(ideal)
    if idcg == 0:
        return 0.0
    return round(dcg(gains) / idcg, 4)

def bm25_topk(corpus, query, k, k1=1.5, b=0.75):
    import math
    n = len(corpus)
    if n == 0:
        return []
    avgdl = sum(len(d) for d in corpus) / n
    df = {}
    for t in set(query):
        df[t] = sum(1 for d in corpus if t in d)
    idf = {}
    for t in set(query):
        idf[t] = math.log(1 + (n - df[t] + 0.5) / (df[t] + 0.5))
    scored = []
    for i, d in enumerate(corpus):
        dl = len(d)
        s = 0.0
        for t in set(query):
            f = d.count(t)
            if f == 0:
                continue
            denom = f + k1 * (1 - b + b * dl / avgdl) if avgdl > 0 else f
            s += idf[t] * (f * (k1 + 1)) / denom
        scored.append([i, round(s, 4)])
    scored.sort(key=lambda p: (-p[1], p[0]))
    if k < 0:
        k = 0
    return scored[:k]

def weighted_rrf(rankings, weights, k):
    scores = {}
    for lst, w in zip(rankings, weights):
        for rank, doc in enumerate(lst, start=1):
            scores[doc] = scores.get(doc, 0.0) + w * (1.0 / (k + rank))
    out = [[doc, round(s, 6)] for doc, s in scores.items()]
    out.sort(key=lambda p: (-p[1], p[0]))
    return out

def sliding_window_sentence_chunk(sentences, max_tokens, overlap_sentences):
    n = len(sentences)
    if n == 0:
        return []
    tok = [len(s.split()) for s in sentences]
    chunks = []
    i = 0
    while i < n:
        j = i
        cur = 0
        while j < n:
            if j > i and cur + tok[j] > max_tokens:
                break
            cur += tok[j]
            j += 1
        chunks.append([sentences[x] for x in range(i, j)])
        if j >= n:
            break
        nxt = j - overlap_sentences
        if nxt <= i:
            nxt = i + 1
        i = nxt
    return chunks

def hybrid_rerank_pipeline(dense, sparse, doc_vectors, doc_tokens, budget, k_final, lambda_, rrf_k):
    import math
    def cos(a, b):
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(y * y for y in b))
        if na == 0 or nb == 0:
            return 0.0
        return dot / (na * nb)
    rrf = {}
    for lst in (dense, sparse):
        for rank, doc in enumerate(lst, start=1):
            rrf[doc] = rrf.get(doc, 0.0) + 1.0 / (rrf_k + rank)
    if not rrf:
        return []
    vals = list(rrf.values())
    lo, hi = min(vals), max(vals)
    rel = {}
    for d, s in rrf.items():
        rel[d] = 1.0 if hi == lo else (s - lo) / (hi - lo)
    remaining = set(rrf.keys())
    selected = []
    used = 0
    while len(selected) < k_final:
        best = None
        best_score = None
        for d in sorted(remaining):
            if used + doc_tokens[d] > budget:
                continue
            if not selected:
                score = rel[d]
            else:
                max_sim = max(cos(doc_vectors[d], doc_vectors[s]) for s in selected)
                score = lambda_ * rel[d] - (1 - lambda_) * max_sim
            if best_score is None or score > best_score:
                best_score = score
                best = d
        if best is None:
            break
        selected.append(best)
        used += doc_tokens[best]
        remaining.discard(best)
    return selected

def evaluate_retrieval_suite(queries, k):
    import math
    if not queries:
        return {"recall@k": 0.0, "mrr": 0.0, "ndcg@k": 0.0}
    def dcg(gains):
        return sum(g / math.log2(i + 2) for i, g in enumerate(gains))
    rs, ms, ns = [], [], []
    for q in queries:
        retrieved = q["retrieved"]
        relevance = q["relevant"]
        rel_ids = {d for d, g in relevance.items() if g > 0}
        topk = retrieved[:k] if k > 0 else []
        if rel_ids:
            rs.append(len(rel_ids & set(topk)) / len(rel_ids))
        else:
            rs.append(0.0)
        rr = 0.0
        for rank, d in enumerate(retrieved, start=1):
            if relevance.get(d, 0) > 0:
                rr = 1.0 / rank
                break
        ms.append(rr)
        gains = [relevance.get(d, 0) for d in topk]
        ideal = sorted(relevance.values(), reverse=True)[:k] if k > 0 else []
        idcg = dcg(ideal)
        ns.append(dcg(gains) / idcg if idcg > 0 else 0.0)
    return {
        "recall@k": round(sum(rs) / len(rs), 4),
        "mrr": round(sum(ms) / len(ms), 4),
        "ndcg@k": round(sum(ns) / len(ns), 4),
    }
